import json,re
C='cases/AMD-0000002488-26-000191-r2'; S=C+'/snapshot'
fx={x['fact_id']:x for x in json.load(open(S+'/facts.json'))['facts']}
cut='2026-11-03T23:00:17Z'
v=json.load(open(C+'/rounds/round-002/numerical/recompute/values.json'))
h=json.load(open(C+'/rounds/round-002/numerical/recompute/history.json'))
d={}
def walk(o):
    if isinstance(o,dict):
        if 'id' in o and 'components' in o: d[o['id']]=o
        for x in o.values(): walk(x)
    elif isinstance(o,list):
        for x in o: walk(x)
walk(h)
def chk(i):
    if i.startswith('F-'):
        x=fx.get(i); 
        if not x: return f'{i} MISSING'
        return f"{i} {x['concept']} {x['start']}..{x['end']} {x['val']} {x['form']} acc {x['acceptance_utc']} {'LEAK' if x['acceptance_utc']>cut else ''}"
    if i.startswith('D-'):
        x=d[i]; return f"{i} {x['formula']} = {x['val']} [" + '; '.join(chk(c) for c in x['components'])+']'
    return i
for k,e in v.items():
    for s in e['sources']:
        if s[:2] in ('F-','D-'): print(k, chk(s))
# all facts in snapshot before cutoff?
print('max acceptance', max(x['acceptance_utc'] for x in fx.values()))
EOF

